window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[331]={"id":"331","numero":331,"titre":"Arrêt cardio-circulatoire","objectifs":[{"id":"331-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un arrêt cardio-circulatoire","contenu":"<p>L'<span class=\"kw-def\">arrêt cardio-circulatoire</span> (<span class=\"kw-alerte\">ACR</span>) est défini par la <strong>cessation de l'activité mécanique cardiaque</strong>, confirmée cliniquement par l'<strong>absence de pouls</strong> associée à une <span class=\"kw-clinique\">apnée</span> ou une <span class=\"kw-clinique\">respiration agonique</span> (« gasping »).</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Mort subite</span></strong></td><td>Mort instantanée et soudaine ; <span class=\"kw-clinique\">les</span> symptômes qui la précèdent ne dépassent pas <span class=\"kw-chiffre\">&lt; 1 h</span> ; <strong>sans cause extracardiaque évidente</strong> (intoxication, traumatisme, <span class=\"kw-alerte\">asphyxie</span> exclus)</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">ACR</span></strong></td><td>Cessation de l'activité mécanique cardiaque, confirmée par l'<strong>absence de pouls</strong> + <span class=\"kw-clinique\">apnée</span> ou <span class=\"kw-clinique\">respiration agonique</span> (gasping)</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">ACR</span> réfractaire</strong></td><td>Absence de récupération d'une circulation spontanée après <strong><span class=\"kw-chiffre\">30 minutes</span></strong> de <span class=\"kw-alerte\">réanimation</span> médicale bien conduite</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">ACR</span> récupéré</strong></td><td><span class=\"kw-alerte\">ACR</span> réanimé avec succès : <strong>hémodynamique stable récupérée</strong> (pouls et pression artérielle convenables)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">gasps</span> (mouvements respiratoires réflexes inefficaces) ont la <strong>même signification que l'absence de respiration</strong> — ils ne doivent jamais faire récuser le diagnostic d'<span class=\"kw-alerte\">ACR</span>.</div>","frequence":0},{"id":"331-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la chaîne de survie","contenu":"<p>La <span class=\"kw-def\">chaîne de survie</span> est la succession des maillons qui conditionnent la survie d'une victime d'<span class=\"kw-alerte\">ACR</span>. La fiche Collège en décrit <strong>5 maillons</strong> ; la fiche EDN.fr récente en compte <strong>6</strong> (ajout de la réhabilitation).</p>\n      <table >\n        <thead><tr><th>Maillon</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 — Alerte précoce</strong></td><td>Dès le diagnostic : <strong><span class=\"kw-alerte\">SAMU</span> (<span class=\"kw-chiffre\">15</span>)</strong> ou pompiers (<span class=\"kw-chiffre\">18</span>), secours (<span class=\"kw-chiffre\">112</span>)</td></tr>\n          <tr><td><strong>2 — <span class=\"kw-def\">RCP</span> précoce</strong></td><td><span class=\"kw-alerte\">Réanimation</span> cardiopulmonaire : <strong>MCE</strong> + assistance ventilatoire</td></tr>\n          <tr><td><strong>3 — Défibrillation précoce</strong></td><td><span class=\"kw-alerte\">Choc</span> électrique externe dès qu'un <span class=\"kw-ttt\">défibrillateur</span> est disponible</td></tr>\n          <tr><td><strong>4 — <span class=\"kw-def\">RCP</span> spécialisée</strong></td><td><span class=\"kw-alerte\">Réanimation</span> médicalisée débutée sur place par le SMUR</td></tr>\n          <tr><td><strong>5 — Soins post-arrêt</strong></td><td>Soins spécialisés post-arrêt cardiaque (<span class=\"kw-alerte\">réanimation</span>)</td></tr>\n          <tr><td><strong>6 — Réhabilitation</strong></td><td>Maillon ajouté par la fiche EDN.fr récente : récupération et réhabilitation du patient</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Notion clé.</strong> L'<strong>absence d'un seul maillon supprime tout espoir de succès</strong>. En France, <span class=\"kw-clinique\">les</span> 3 premiers maillons restent faibles.</div>\n      <div class=\"callout callout-warn\"><strong>Facteurs de meilleur <span class=\"kw-def\">pronostic</span>.</strong> Présence d'un <strong>témoin</strong> ; <strong><span class=\"kw-alerte\">réanimation</span> précoce</strong> ; <strong><span class=\"kw-alerte\">FV</span> initiale</strong> ; <strong>défibrillation rapide</strong> ; durée courte de la réanimation.</div>","frequence":0},{"id":"331-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence et le pronostic de l’arrêt cardio-circulatoire chez l’adulte et l’enfant","contenu":"<p>L'<span class=\"kw-alerte\">ACR</span> est un événement <strong>fréquent et de <span class=\"kw-def\">pronostic</span> sombre</strong> : la <span class=\"kw-def\">mortalité</span> globale dépasse <strong><span class=\"kw-chiffre\">90 %</span></strong>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Chez l'adulte</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Incidence</span></strong></td><td><span class=\"kw-chiffre\">7,5 / 10 000</span> en France (≈ <span class=\"kw-chiffre\">40 000-50 000</span> décès/an)</td></tr>\n          <tr><td><strong>Âge · sexe</strong></td><td>Âge moyen <span class=\"kw-chiffre\">60 ans</span> ; prédominance masculine <span class=\"kw-chiffre\">2H / 1F</span></td></tr>\n          <tr><td><strong>Lieu</strong></td><td>Le plus souvent <strong>hors de l'hôpital</strong> : <span class=\"kw-chiffre\">75 %</span> à domicile ; témoin présent dans <span class=\"kw-chiffre\">70 %</span> des cas, mais <strong>seuls <span class=\"kw-chiffre\">40 %</span> des témoins réalisent la <span class=\"kw-def\">RCP</span></strong></td></tr>\n          <tr><td><strong>Survie</strong></td><td>Intra-hospitalier <span class=\"kw-chiffre\">10-15 %</span> ; extra-hospitalier <span class=\"kw-chiffre\">5-7 %</span> ; survie sans séquelles ≈ <span class=\"kw-chiffre\">2-4 %</span></td></tr>\n          <tr><td><strong>Mécanisme du décès</strong></td><td><span class=\"kw-alerte\">Défaillance</span> multiviscérale (<span class=\"kw-alerte\">choc</span> post-arrêt) dans 1/3 des cas ; <span class=\"kw-alerte\">encéphalopathie post-anoxique</span> dans 2/3 des cas</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs pronostiques :</strong> présence d'un témoin ; durée du <strong>no-flow</strong> ; rapidité de mise en œuvre de la <span class=\"kw-def\">RCP</span> ; <span class=\"kw-def\">terrain</span> ; séquelles cardiaques et neurologiques. La survie décroît de <strong><span class=\"kw-chiffre\">-10 % par minute</span></strong> écoulée sans <span class=\"kw-alerte\">réanimation</span> (proche de 0 après <span class=\"kw-chiffre\">10 min</span>). Meilleur <span class=\"kw-def\">pronostic</span> en cas de <strong><span class=\"kw-alerte\">FV</span></strong> que d'<span class=\"kw-alerte\">asystolie</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Chez l'enfant.</strong> L'<span class=\"kw-alerte\">ACR</span> est <strong><span class=\"kw-chiffre\">15×</span> moins fréquent</strong> que chez l'adulte ; le <span class=\"kw-def\">pronostic</span> est très sombre : <strong>survie &lt; <span class=\"kw-chiffre\">5 %</span> à<span class=\"kw-chiffre\"> 1 an</span></strong>.</div>","frequence":0},{"id":"331-4","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’arrêt cardio-circulatoire chez l’adulte et chez l’enfant","contenu":"<p>Le <strong>mécanisme électrique initial</strong> le plus fréquent est la <strong><span class=\"kw-alerte\">FV</span></strong> &gt; bradycardies extrêmes (BAV de haut <span class=\"kw-def\">grade</span>) &gt; <span class=\"kw-alerte\">asystolie</span>. Sur le plan étiologique, l'origine est <strong>cardiovasculaire dans la grande majorité des cas</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">SCA</span></strong><br>(<span class=\"kw-chiffre\">80 %</span>)</td><td><strong>Principale étiologie de l'<span class=\"kw-alerte\">ACR</span></strong> : <span class=\"kw-etio\">syndrome coronarien aigu</span>, par un mécanisme de trouble du rythme ventriculaire (<span class=\"kw-alerte\">FV</span>/TV)</td></tr>\n          <tr><td><strong>Autres causes cardiovasculaires</strong></td><td>\n            <strong>Cardiomyopathies :</strong> <span class=\"kw-etio\">CMH</span> (surtout obstructive/familiale) ; <span class=\"kw-etio\">CMD</span> ; <span class=\"kw-etio\">DAVD</span> ; valvulopathies (RAo surtout)<br>\n            <strong>Rythme/conduction sur cœur sain :</strong> <span class=\"kw-alerte\">FV</span> idiopathique ; <span class=\"kw-etio\">Brugada</span> ; QT long ; QT court ; WPW<br>\n            <strong>Autres :</strong> myocardite aiguë ; <span class=\"kw-alerte\">tamponnade</span> ; <span class=\"kw-etio\">dissection</span> aortique ; <span class=\"kw-etio\">EP massive</span> ; <span class=\"kw-alerte\">rupture</span> d'anévrisme ; cardiopathies congénitales\n          </td></tr>\n          <tr><td><strong>Causes non cardiovasculaires</strong><br>(<span class=\"kw-chiffre\">5-25 %</span>)</td><td>Causes <span class=\"kw-etio\">toxiques</span> ; <span class=\"kw-etio\">traumatiques</span> ; <span class=\"kw-etio\">insuffisances respiratoires aiguës</span> ; <span class=\"kw-etio\">noyades</span> — généralement orientées par le contexte</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Chez l'enfant.</strong> Contrairement à l'adulte (origine cardiaque), l'<span class=\"kw-alerte\">ACR</span> de l'enfant est le plus souvent <strong>secondaire</strong> — mécanisme dominant : l'<span class=\"kw-etio\">hypoxie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 236 — Trouble de conduction intracardiaque · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique</em></p>","frequence":0},{"id":"331-5","rang":"B","rubrique":"Définition","titre":"Connaître le no-flow et low flow","contenu":"<p>Deux durées conditionnent le <span class=\"kw-def\">pronostic</span> de l'<span class=\"kw-alerte\">ACR</span> : le <strong>no-flow</strong> et le <strong>low-flow</strong>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>No-flow</th><th>Low-flow</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Temps entre la survenue de l'<span class=\"kw-alerte\">ACR</span> et le <strong>début de la <span class=\"kw-def\">RCP</span></strong> (massage cardiaque)</td><td>Temps entre le <strong>début du MCE</strong> et la reprise d'une activité circulatoire (= temps de <span class=\"kw-alerte\">réanimation</span>)</td></tr>\n          <tr><td><strong>Débit cardiaque</strong></td><td><strong>Nul</strong> — aucune mécanique cardiaque efficace</td><td><strong>Bas</strong> — le MCE n'assure que <span class=\"kw-chiffre\">10 à 25 %</span> du débit de base</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pronostic</span> associé</strong></td><td><span class=\"kw-def\">Pronostic</span> <strong><span class=\"kw-alerte\">neurologique</span></strong> ++</td><td>Syndrome de <strong><span class=\"kw-alerte\">défaillance multiviscérale</span></strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Seuils du no-flow.</strong> Très mauvais <span class=\"kw-def\">pronostic</span> si <strong><span class=\"kw-chiffre\">&gt; 5 minutes</span></strong> ; survie quasi nulle ou survie avec état végétatif (lésions cérébrales) si <strong><span class=\"kw-chiffre\">&gt; 10 minutes</span></strong>.</div>","frequence":0},{"id":"331-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les besoins de ventilation de base","contenu":"<p>La ventilation de base s'intègre dans la séquence <strong>A-B</strong> de la <span class=\"kw-alerte\">réanimation</span>, sans jamais retarder le massage cardiaque.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A — Airway</strong><br>(libération des VAS)</td><td>\n            Bascule de la tête en arrière + subluxation de la mâchoire — <span class=\"kw-alerte\">sauf suspicion de traumatisme cervical</span> (traumatologie, noyade avec plongeon, <span class=\"kw-clinique\">convulsions</span>, électrisation)<br>\n            Vérification et retrait des corps étrangers (doigts en crochet)<br>\n            Canule oropharyngée (canule de Guedel) si disponible\n          </td></tr>\n          <tr><td><strong>B — Breathing</strong><br>(ventilation)</td><td>\n            Bouche-à-bouche : <strong>plus recommandé pour le grand public</strong>, reste la méthode de choix pour <span class=\"kw-clinique\">les</span> professionnels<br>\n            Ventilation au <strong>BAVU</strong> (ballon auto-remplisseur à valve unidirectionnelle) ± source d'O₂<br>\n            Durée d'insufflation ≈ <span class=\"kw-chiffre\">1 s</span> ; rythme <strong>30 compressions : 2 insufflations</strong>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège majeur.</strong> L'<strong><span class=\"kw-alerte\">hyperventilation est néfaste</span></strong> : elle diminue le retour veineux en augmentant la pression intra-thoracique.</div>\n      <p>Après <span class=\"kw-ttt\">intubation</span> : insufflations à <span class=\"kw-chiffre\">10/min</span>, indépendantes du MCE qui devient continu ; <strong>FiO₂ à <span class=\"kw-chiffre\">100 %</span></strong> durant l'<span class=\"kw-alerte\">arrêt cardiaque</span> ; débit d'O₂ ≥ <span class=\"kw-chiffre\">15 L/min</span> sur le BAVU.</p>","frequence":0},{"id":"331-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître l’algorithme universel de réanimation cardiopulmonaire de l’adulte","contenu":"<p>L'algorithme universel de <span class=\"kw-def\">RCP</span> de l'adulte enchaîne la <strong><span class=\"kw-alerte\">réanimation</span> de base</strong> (MCE + ventilation) et l'<strong>analyse du rythme</strong>, qui sépare deux branches : rythme <strong>choquable</strong> ou <strong>non choquable</strong>.</p>\n      <p><strong>Massage cardiaque externe (MCE) — la priorité.</strong> Patient en décubitus dorsal sur un plan dur, sauveteur agenouillé ; mains au centre du thorax (moitié inférieure du sternum), bras tendus ; compressions de <strong><span class=\"kw-chiffre\">5-6 cm</span></strong> à une fréquence de <strong><span class=\"kw-chiffre\">100-120/min</span></strong> ; ratio <strong>30:2</strong> ; relais des sauveteurs <strong>toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 min</span></strong>.</p>\n      <table >\n        <thead><tr><th>Branche</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Rythme choquable</strong><br>(<span class=\"kw-alerte\">FV</span>, TV sans pouls)</td><td>\n            <strong>1 <span class=\"kw-ttt\">CEE</span></strong> (<span class=\"kw-chiffre\">150 J</span> biphasique) puis <strong><span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span></strong> avant de réévaluer<br>\n            Si persistance : <strong>2ᵉ CEE</strong> puis RCP <span class=\"kw-chiffre\">2 min</span><br>\n            Si persistance : <strong>3ᵉ CEE</strong> puis RCP <span class=\"kw-chiffre\">2 min</span> + <span class=\"kw-ttt\">adrénaline 1 mg</span> + <span class=\"kw-ttt\">amiodarone 300 mg</span><br>\n            Si persistance : <strong>4ᵉ CEE</strong> puis RCP <span class=\"kw-chiffre\">2 min</span> + <span class=\"kw-ttt\">adrénaline 1 mg</span> + <span class=\"kw-ttt\">amiodarone 150 mg</span>\n          </td></tr>\n          <tr><td><strong>Rythme non choquable</strong><br>(<span class=\"kw-alerte\">asystolie</span>, AESP)</td><td>\n            <strong>Pas de <span class=\"kw-alerte\">choc</span></strong><br>\n            <span class=\"kw-ttt\">Adrénaline 1 mg</span> IVD toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 min</span>, dès le début<br>\n            Poursuite de la <span class=\"kw-def\">RCP</span> ; <span class=\"kw-def\">réévaluation</span> du rythme et du pouls toutes les <span class=\"kw-chiffre\">2 min</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesures associées</strong> (menées sans interrompre le MCE) : abord vasculaire ; <span class=\"kw-ttt\">intubation</span> et ventilation ; MCE en continu ; <strong>traiter une cause</strong> réversible (4H/4T).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/331/algorithme-rcp-universel-adulte.png\" alt=\"Algorithme de réanimation cardiopulmonaire universel de l'adulte : analyse du rythme, branche choquable (CEE itératifs, adrénaline et amiodarone) et branche non choquable (adrénaline, RCP)\" loading=\"lazy\">\n        <figcaption>Algorithme universel de <span class=\"kw-def\">RCP</span> de l'adulte. Source : American Heart Association 2020, fiche source EDN item 331.</figcaption>\n      </figure>","frequence":4},{"id":"331-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes d’utilisation d’un scope/défibrillateur manuel/semi-automatique","contenu":"<p>La <span class=\"kw-def\">défibrillation</span> consiste à faire passer un courant électrique à travers le cœur pour entraîner une <strong>dépolarisation simultanée d'une <span class=\"kw-clinique\">masse</span> critique de cellules myocardiques</strong>, ce qui interrompt <span class=\"kw-clinique\">les</span> phénomènes de réentrée (arrêt d'une <span class=\"kw-alerte\">FV</span> ou d'une TV).</p>\n      <table >\n        <thead><tr><th>Item</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Énergie</strong></td><td>Ondes <strong>biphasiques</strong> de <span class=\"kw-chiffre\">150-200 J</span> (ancienne génération monophasique :<span class=\"kw-chiffre\"> 360 J</span>)</td></tr>\n          <tr><td><strong>DAE</strong></td><td>Défibrillateurs automatisés externes disponibles dans <span class=\"kw-clinique\">les</span> lieux publics ; applications smartphone pour les localiser (« Staying Alive », « SAUV Life »)</td></tr>\n          <tr><td><strong>Placement des électrodes</strong></td><td>1 électrode <strong>sous le mamelon gauche</strong> ; 1 électrode <strong>sous la clavicule droite</strong>, sur la ligne médio-claviculaire</td></tr>\n          <tr><td><strong>Analyse du rythme</strong></td><td><span class=\"kw-def\">Réévaluation</span> du rythme <strong>toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 min</span></strong></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Rythmes choquables</th><th>Rythmes non choquables</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">FV</span> ; <span class=\"kw-clinique\">TV sans pouls</span> ; <span class=\"kw-clinique\">torsade de pointe</span></td><td><span class=\"kw-clinique\">Asystolie</span> (tracé plat) ; <span class=\"kw-clinique\">dissociation électromécanique</span> (activité électrique sans pouls, QRS fins ou larges)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/331/trace-ecg-rythmes-acr.png\" alt=\"Tracés ECG des rythmes d'arrêt cardiaque : fibrillation ventriculaire, TV sans pouls, torsade de pointe (choquables), asystolie et dissociation électromécanique (non choquables)\" loading=\"lazy\">\n        <figcaption>Reconnaissance des rythmes d'<span class=\"kw-alerte\">arrêt cardiaque</span> sur le scope. Source : fiche source EDN item 331.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <strong><span class=\"kw-alerte\">FV</span></strong> est le rythme initial le plus fréquent (<span class=\"kw-chiffre\">40-70 %</span> des cas) ; le <span class=\"kw-ttt\">CEE</span> en est le seul traitement, idéalement délivré <span class=\"kw-chiffre\">&lt; 3 min</span>. L'<strong><span class=\"kw-alerte\">asystolie</span></strong> témoigne le plus souvent d'un no-flow prolongé : c'est un <span class=\"kw-alerte\">facteur pronostique péjoratif</span> — on fait le MCE, pas un <span class=\"kw-alerte\">choc</span>.</div>","frequence":0},{"id":"331-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les voies d’abord vasculaire d’urgence","contenu":"<p>L'accès vasculaire est l'une des mesures associées de la <span class=\"kw-def\">RCP</span> médicalisée, à obtenir sans interrompre le massage.</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 — VVP</strong></td><td>Voie veineuse périphérique en <strong>1ʳᵉ intention</strong> ; ne pas perdre <span class=\"kw-chiffre\">&gt; 3 min</span> à tenter de la poser, sinon passer à la 2ᵉ intention</td></tr>\n          <tr><td><strong>2 — Voie intra-osseuse</strong></td><td>\n            En l'absence de VVP accessible, parfois d'emblée en préhospitalier<br>\n            <strong>Sites :</strong> extrémités supérieure ou distale des tibias (plateau tibial) ; extrémité supérieure de l'humérus<br>\n            <strong>Toutes <span class=\"kw-clinique\">les</span> thérapeutiques</strong> peuvent y être administrées (cristalloïdes, catécholamines, PSL)<br>\n            <strong>Temporaire :</strong> à retirer &lt; <span class=\"kw-chiffre\">24 h</span> (relais par une voie veineuse dès l'arrivée en <span class=\"kw-alerte\">réanimation</span>)\n          </td></tr>\n          <tr><td><strong>3 — VVC</strong></td><td>Voie veineuse centrale = <strong>2ᵉ intention</strong> ; cathéter fémoral, jugulaire ou sous-clavier (méthode de Seldinger), en asepsie chirurgicale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À ne plus faire.</strong> La <span class=\"kw-ci\">voie intra-trachéale</span> n'est plus recommandée (biodisponibilité très aléatoire, interruption obl<span class=\"kw-chiffre\">iga</span>toire de la <span class=\"kw-def\">RCP</span>).</div>","frequence":0},{"id":"331-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement médicamenteux (adrénaline) de la prise en charge initiale d’un rythme non choquable","contenu":"<p>En présence d'un <strong>rythme non choquable</strong> (<span class=\"kw-alerte\">asystolie</span>, AESP / dissociation électromécanique), il n'y a <strong>pas d'indication au <span class=\"kw-alerte\">choc</span></strong> : le traitement <span class=\"kw-etio\">médicamenteux</span> repose sur l'<span class=\"kw-ttt\">adrénaline</span>, traitement <strong>incontournable</strong> de cette situation.</p>\n      <ul>\n        <li><strong>Posologie :</strong> <span class=\"kw-ttt\">adrénaline 1 mg</span> IVD toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 min</span>, <strong>dès le début de la prise en charge</strong>.</li>\n        <li><strong>Mécanisme :</strong> ses effets bénéfiques sont principalement dus aux récepteurs <strong><span class=\"kw-def\">alpha-adrénergiques</span></strong> — augmentation des débits sanguins myocardique et cérébral pendant la <span class=\"kw-alerte\">réanimation</span>.</li>\n        <li><strong>Conduite :</strong> poursuite du MCE pendant <span class=\"kw-chiffre\">2 min</span> puis réanalyse du rythme ; le <span class=\"kw-ttt\">CEE</span> reste inutile tant que le rythme est non choquable.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Dans l'<span class=\"kw-alerte\">ACR</span> <strong>réfractaire en <span class=\"kw-alerte\">asystolie</span></strong>, l'<span class=\"kw-ttt\">adrénaline</span> est <strong>le</strong> traitement <span class=\"kw-etio\">médicamenteux</span> de référence.</div>","frequence":0},{"id":"331-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les traitements médicamenteux de la réanimation cardiopulmonaire (dont la posologie de l’adrénaline par voie intraveineuse)","contenu":"<p>Au-delà de l'<span class=\"kw-ttt\">adrénaline</span>, plusieurs molécules interviennent dans la <span class=\"kw-def\">RCP</span> médicalisée.</p>\n      <table >\n        <thead><tr><th>Médicament</th><th>Indications · posologie</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Adrénaline</span></strong></td><td>\n            <strong>Posologie :</strong> <span class=\"kw-chiffre\">1 mg</span> IV (ou endotrachéale), à répéter — <strong><span class=\"kw-chiffre\">1 mg</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 min</span></strong> (soit tous les 2 cycles de <span class=\"kw-def\">RCP</span>)<br>\n            <strong>Rythme non choquable :</strong> dès le début de la PEC<br>\n            <strong>Rythme choquable :</strong> après le 3ᵉ <span class=\"kw-ttt\">CEE</span>\n          </td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Amiodarone</span></strong></td><td>\n            Anti-arythmique des <span class=\"kw-alerte\">FV</span>/TV réfractaires aux <span class=\"kw-ttt\">CEE</span><br>\n            <strong>Dose initiale :</strong> <span class=\"kw-chiffre\">300 mg</span> en bolus IV, après le 3ᵉ CEE<br>\n            <strong>Dose supplémentaire :</strong> <span class=\"kw-chiffre\">150 mg</span> ; relais <span class=\"kw-chiffre\">900 mg/24 h IVSE</span> après retour en rythme sinusal<br>\n            <strong>Particularité :</strong> l'<span class=\"kw-alerte\">ACR</span> est la seule situation où un anti-arythmique s'administre en bolus\n          </td></tr>\n          <tr><td><strong>Autres anti-arythmiques</strong></td><td>\n            <span class=\"kw-ttt\">Lidocaïne</span> : seulement si l'<span class=\"kw-ttt\">amiodarone</span> n'est pas disponible<br>\n            <span class=\"kw-ttt\">Sulfate de magnésium</span> : torsade de pointe ou suspicion d'hypomagnésémie\n          </td></tr>\n          <tr><td><strong>Bradycardies extrêmes</strong></td><td>\n            <span class=\"kw-ttt\">Atropine</span> : bradycardies sinusales extrêmes<br>\n            <span class=\"kw-ttt\">Isoprénaline</span> : BAV du 3ᵉ degré sans hémodynamique efficace (objectif FC ≥ <span class=\"kw-chiffre\">50-60</span>)\n          </td></tr>\n          <tr><td><strong>Alcalinisation</strong></td><td><span class=\"kw-ttt\">Bicarbonate de sodium 8,4 %</span> : <span class=\"kw-alerte\">réanimation</span> prolongée ; hyperkaliémie ; acidose préexistante ; intoxication aux stabilisants de membrane (tricycliques, <span class=\"kw-ttt\">phénobarbital</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Thrombolyse</span></strong></td><td>Non systématique ; au cas par cas si <span class=\"kw-etio\">IDM</span> ou <span class=\"kw-etio\">EP massive</span> avérés ou fortement suspectés</td></tr>\n          <tr><td><strong>Remplissage</strong></td><td>Sérum salé isotonique <strong>seulement si <span class=\"kw-alerte\">ACR</span> d'origine hypovolémique</strong> ; sinon non recommandé, voire <span class=\"kw-alerte\">délétère</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"331-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités diagnostiques et de traitement étiologique de l’arrêt cardio-circulatoire","contenu":"<p>Dès la récupération d'une activité circulatoire (RACS), un <strong><span class=\"kw-bio\">ECG immédiat</span></strong> recherche un <span class=\"kw-def\">SCA</span> — cause la plus fréquente d'<span class=\"kw-alerte\">ACR</span>.</p>\n      <ul>\n        <li><strong>Sus-décalage du ST :</strong> <span class=\"kw-imagerie\">coronarographie</span> immédiate, à visée diagnostique et thérapeutique.</li>\n        <li><strong>Pas de sus-ST :</strong> rechercher une cause extra-cardiaque ; si aucune n'est retrouvée, <span class=\"kw-imagerie\">coronarographie</span> à envisager rapidement.</li>\n      </ul>\n      <p><strong>Causes réversibles — <span class=\"kw-clinique\">les</span> 4H / 4T</strong> à évoquer systématiquement pendant la <span class=\"kw-def\">RCP</span> :</p>\n      <table >\n        <thead><tr><th>Cause réversible</th><th>Signes évocateurs</th><th>Traitement en <span class=\"kw-alerte\">urgence</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hypoxie</strong></td><td><span class=\"kw-alerte\">Détresse</span> respiratoire, désaturation</td><td>Oxygénation, <span class=\"kw-ttt\">intubation</span>, recherche d'un corps étranger</td></tr>\n          <tr><td><strong>Hypovolémie</strong></td><td>Contexte clinique</td><td>Expansion volémique</td></tr>\n          <tr><td><strong>Hypo/hyperkaliémie</strong></td><td>Médicaments, <span class=\"kw-ci\">insuffisance rénale</span></td><td>Correction électrolytique (K⁺, Mg²⁺) ; gluconate de calcium + <span class=\"kw-bio\">bicarbonates</span> + <span class=\"kw-ttt\">insuline</span>/glucose</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Hypothermie</span></strong></td><td>Contexte, température</td><td>Réchauffement ± assistance circulatoire</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Tamponnade</span></strong></td><td>Signes d'<span class=\"kw-def\">insuffisance cardiaque</span> droite</td><td><span class=\"kw-ttt\">Drainage</span> péricardique</td></tr>\n          <tr><td><strong>Tension (PNO compressif)</strong></td><td><span class=\"kw-clinique\">Asymétrie</span> auscultatoire, IC droite</td><td>Exsufflation puis <span class=\"kw-ttt\">drainage</span> thoracique</td></tr>\n          <tr><td><strong>Thrombose (<span class=\"kw-def\">SCA</span>, EP)</strong></td><td><span class=\"kw-bio\">ECG</span>, signes de cœur droit aigu</td><td><span class=\"kw-imagerie\">Coronarographie</span> (<span class=\"kw-def\">SCA</span>) ; <span class=\"kw-ttt\">thrombolyse</span> (EP)</td></tr>\n          <tr><td><strong>Toxiques</strong></td><td>Contexte ; QRS larges (stabilisants de membrane)</td><td>Antidote ; <span class=\"kw-bio\">bicarbonates</span> molaires</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Éléments d'orientation :</strong> rythme pendant la <span class=\"kw-def\">RCP</span> ; anamnèse ; auscultation pulmonaire (PNO) ; inspection des jugulaires (cœur droit aigu) ; <span class=\"kw-bio\">ionogramme</span> et <span class=\"kw-bio\">gazométrie</span> (dyskaliémie) ; <span class=\"kw-imagerie\">ETT</span> (cœur pulmonaire aigu, <span class=\"kw-imagerie\">épanchement péricardique</span>).</p>\n      <p><strong>Prise en charge post-arrêt cardiaque.</strong> Après le RACS, le <span class=\"kw-def\">pronostic</span> dépend de la récupération myocardique et surtout neurologique. Trois volets : poursuite de l'enquête étiologique ; prise en charge des complications post-arrêt ; <strong>neuroprotection et contrôle des ACSOS</strong>.</p>\n      <table >\n        <thead><tr><th>Cible</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fonction cardiaque</strong></td><td>Sidération myocardique fréquente ; <span class=\"kw-ttt\">dobutamine</span> en cas de trouble de la contractilité ; <strong>ECMO</strong> si <span class=\"kw-alerte\">ACR</span> réfractaire</td></tr>\n          <tr><td><strong>Fonction cérébrale</strong></td><td>Lutte contre <span class=\"kw-clinique\">les</span> ACSOS (oxygénation, objectif SpO₂ <span class=\"kw-chiffre\">94-98 %</span> ; <span class=\"kw-bio\">glycémie</span>) ; <span class=\"kw-ttt\">sédation</span> <span class=\"kw-chiffre\">24-48 h</span> ; contrôle thermique ciblé <span class=\"kw-chiffre\">32-36 °C</span> <span class=\"kw-chiffre\">≥ 24 h</span> ; <span class=\"kw-alerte\">l'hyperthermie laisse des séquelles</span> et doit être prévenue</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 235 — Péricardite aiguë · 360 — <span class=\"kw-imagerie\">Pneumothorax</span> · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique</em></p>","frequence":0},{"id":"331-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les critères d’arrêt de la réanimation","contenu":"<p>L'arrêt de la <span class=\"kw-alerte\">réanimation</span> est <strong>toujours une décision médicale</strong>, collégiale, et orientée par <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">EEG répétés</span> (qui témoignent de la mort cérébrale).</p>\n      <div class=\"callout callout-danger\"><strong>Règle des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>30</span> min</span>utes.</strong> Après <strong>échec de <span class=\"kw-chiffre\">30 min</span> de <span class=\"kw-def\">RCP</span> spécialisée</strong> bien conduite, la <span class=\"kw-alerte\">réanimation</span> peut être arrêtée — <span class=\"kw-alerte\">en l'absence de facteur de protection cérébrale</span> : <strong><span class=\"kw-clinique\">hypothermie</span></strong> (dont noyade) et <strong>intoxications</strong>.</div>\n      <p><strong>Critères d'arrêt d'une <span class=\"kw-def\">RCP</span> extrahospitalière</strong> — arrêt possible si <strong>tous</strong> <span class=\"kw-clinique\">les</span> critères sont réunis :</p>\n      <ul>\n        <li>Arrêt cardiaque <strong>sans témoin</strong> (no-flow inconnu).</li>\n        <li>Rythme <strong>initialement non choquable</strong>.</li>\n        <li><span class=\"kw-clinique\">Asystolie</span> prolongée <strong><span class=\"kw-chiffre\">&gt; 20 min</span></strong> malgré une <span class=\"kw-def\">RCP</span> continue.</li>\n        <li>Absence de <strong>cause réversible</strong> connue.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Directives anticipées.</strong> Lorsqu'un patient a exprimé de son vivant sa volonté de ne pas être réanimé, cette décision doit être respectée si elle a été formulée conformément à la réglementation. Un prélèvement d'organe reste possible si la <span class=\"kw-alerte\">réanimation</span> a été rapide et l'hémodynamique préservée.</div>","frequence":0},{"id":"331-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître l’algorithme universel de réanimation cardiopulmonaire de l’enfant","contenu":"<p>La <span class=\"kw-def\">RCP</span> avancée de l'enfant suit le même schéma que celle de l'adulte, avec des <strong>posologies pondérales</strong> et un rythme d'évaluation par 2 et <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> min</span>utes.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Rythme non choquable</th><th>Rythme choquable</th></tr></thead>\n        <tbody>\n          <tr><td><strong>T0</strong></td><td><span class=\"kw-ttt\">Adrénaline 10 µg/kg</span> IV/IO (=<span class=\"kw-chiffre\"> 0,1 mL</span>/kg de solution à 1/10 000), puis <span class=\"kw-def\">RCP</span></td><td>1ᵉʳ <span class=\"kw-ttt\">CEE</span> <span class=\"kw-chiffre\">4 J/kg</span> puis <span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span> + pose KTIO</td></tr>\n          <tr><td><strong>T0 +<span class=\"kw-chiffre\"> 2 min</span></strong></td><td><span class=\"kw-def\">Réévaluation</span> ; si inchangé → <span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span></td><td><span class=\"kw-def\">Réévaluation</span> ; si inchangé → 2ᵉ <span class=\"kw-ttt\">CEE</span> <span class=\"kw-chiffre\">4 J/kg</span> puis <span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span></td></tr>\n          <tr><td><strong>T0 +<span class=\"kw-chiffre\"> 4 min</span></strong></td><td><span class=\"kw-def\">Réévaluation</span> ; si inchangé → <span class=\"kw-ttt\">adrénaline 10 µg/kg</span> puis <span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span></td><td><span class=\"kw-def\">Réévaluation</span> ; si inchangé → 3ᵉ <span class=\"kw-ttt\">CEE</span> <span class=\"kw-chiffre\">4 J</span>/kg + <span class=\"kw-ttt\">adrénaline 10 µg/kg</span> + <span class=\"kw-ttt\">amiodarone 5 mg/kg</span> puis <span class=\"kw-def\">RCP</span> <span class=\"kw-chiffre\">2 min</span></td></tr>\n          <tr><td><strong>Ensuite</strong></td><td colspan=\"2\">Répéter <span class=\"kw-clinique\">les</span> évaluations et actions <strong>par 2 et <span class=\"kw-chiffre\">4 min</span></strong> — <strong>sans <span class=\"kw-ttt\">amiodarone</span> après le <span class=\"kw-ttt\">CEE</span> n°5</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe systématique.</strong> Évoquer dès que possible <span class=\"kw-clinique\">les</span> <strong>causes réversibles 4H/4T</strong>, particulièrement fréquentes chez l'enfant.</div>","frequence":0},{"id":"331-15","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’épidémiologie et mécanisme de l’arrêt cardiorespiratoire chez l’enfant","contenu":"<p>L'<span class=\"kw-alerte\">ACR</span> de l'enfant (spécificités &lt;<span class=\"kw-chiffre\"> 12 ans</span>) se distingue nettement de celui de l'adulte.</p>\n      <ul>\n        <li><strong>Mécanisme :</strong> <span class=\"kw-alerte\">ACR</span> le plus souvent <strong>secondaire</strong> — cause dominante : l'<span class=\"kw-etio\">hypoxie</span> (≠ origine cardiaque de l'adulte).</li>\n        <li><strong>Rythme :</strong> <span class=\"kw-chiffre\">75 %</span> d'<span class=\"kw-clinique\">asystolie</span> (rythme non choquable).</li>\n        <li><strong>Fréquence :</strong> <span class=\"kw-chiffre\">15×</span> moins fréquent que chez l'adulte.</li>\n        <li><strong><span class=\"kw-def\">Pronostic</span> :</strong> sombre — survie &lt; <span class=\"kw-chiffre\">5 %</span> à<span class=\"kw-chiffre\"> 1 an</span>.</li>\n      </ul>\n      <p><strong>Valeurs normales pédiatriques</strong> (repères selon l'âge) :</p>\n      <table >\n        <thead><tr><th>Âge</th><th>FR (/min)</th><th>FC (/min)</th><th>PAS (mmHg)</th><th>PAM (mmHg)</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">1 mois</span></strong></td><td><span class=\"kw-chiffre\">35-60</span></td><td><span class=\"kw-chiffre\">110-180</span></td><td><span class=\"kw-chiffre\">&lt; 50</span></td><td><span class=\"kw-chiffre\">&lt; 40</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">1 an</span></strong></td><td><span class=\"kw-chiffre\">30-50</span></td><td><span class=\"kw-chiffre\">100-170</span></td><td><span class=\"kw-chiffre\">&lt; 70</span></td><td><span class=\"kw-chiffre\">&lt; 50</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">5 ans</span></strong></td><td><span class=\"kw-chiffre\">17-30</span></td><td><span class=\"kw-chiffre\">70-140</span></td><td><span class=\"kw-chiffre\">&lt; 75</span></td><td><span class=\"kw-chiffre\">&lt; 55</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">10 ans</span></strong></td><td><span class=\"kw-chiffre\">14-25</span></td><td><span class=\"kw-chiffre\">60-120</span></td><td><span class=\"kw-chiffre\">&lt; 80</span></td><td><span class=\"kw-chiffre\">&lt; 55</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>8 causes réversibles pédiatriques.</strong> <strong>4 H :</strong> Hypoxie ; Hypovolémie ; Hypo/hyperkaliémie - <span class=\"kw-bio\">magnésémie</span> - <span class=\"kw-bio\">calcémie</span> - hypoglycémie ; Hypo/<span class=\"kw-clinique\">hyperthermie</span>. <strong>4 T :</strong> PNO sous Tension ; <span class=\"kw-alerte\">Tamponnade</span> ; Toxiques ; Thromboembolique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — <span class=\"kw-clinique\">Malaise</span> grave du nourrisson, <span class=\"kw-alerte\">mort subite</span></em></p>","frequence":0},{"id":"331-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge de l’arrêt cardio-respiratoire de l’enfant : premières minutes","contenu":"<p>La reconnaissance d'un <span class=\"kw-alerte\">ACR</span> de l'enfant doit être rapide (<span class=\"kw-chiffre\">&lt; 10 s</span>) : on recherche l'<strong>absence de signes de vie</strong>. La séquence des premières minutes suit <span class=\"kw-clinique\">les</span> « 3S » puis l'« ABC ».</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>« 3S »</strong></td><td>\n            <strong>Sécurité :</strong> sécuriser le lieu de la victime<br>\n            <strong>Stimulation :</strong> enfant non réveillable, absence de respiration ou gasps, absence de <span class=\"kw-clinique\">toux</span><br>\n            <strong>Secours :</strong> prévenir le <span class=\"kw-alerte\">SAMU</span> / la réanimation ; chariot d'<span class=\"kw-alerte\">urgence</span> et DAE\n          </td></tr>\n          <tr><td><strong>A — Airway</strong></td><td>Ouvrir, désobstruer et sécuriser <span class=\"kw-clinique\">les</span> voies aériennes : position <strong>neutre</strong> chez le nourrisson, hyper-extension après <span class=\"kw-chiffre\">1 an</span></td></tr>\n          <tr><td><strong>B — Breathing</strong></td><td>Évaluation respiratoire (max <span class=\"kw-chiffre\">10 s</span>) : si anormale → <strong>5 ventilations initiales</strong></td></tr>\n          <tr><td><strong>C — Circulation</strong></td><td>Recherche de signes de vie : si absents → <strong>15 compressions thoraciques</strong> puis cycles <strong>15:2</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Compressions thoraciques selon l'âge :</strong></p>\n      <ul>\n        <li><strong>Nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span> :</strong> compressions à 2 doigts, ou à 2 mains par encerclement du thorax (sauveteur seul).</li>\n        <li><strong>Enfant &gt;<span class=\"kw-chiffre\"> 1 an</span> :</strong> compressions au talon d'1 ou 2 mains (selon la taille de l'enfant et du sauveteur).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Expansion volémique.</strong> Si besoin : bolus de <span class=\"kw-chiffre\">10 mL/kg</span> (max <span class=\"kw-chiffre\">500 mL</span> par bolus), à répéter — max <span class=\"kw-chiffre\">40-60 mL/kg</span> sur la 1ʳᵉ heure, en l'absence de signes d'<span class=\"kw-def\">insuffisance cardiaque</span>. Si un rythme organisé &gt;<span class=\"kw-chiffre\"> 60/min</span> apparaît, rechercher un pouls.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 345 — <span class=\"kw-clinique\">Malaise</span> grave du nourrisson, <span class=\"kw-alerte\">mort subite</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale absolue</span> ; <span class=\"kw-def\">pronostic</span> conditionné par le <span class=\"kw-def\">no-flow</span><br><strong>Fenêtre :</strong> survie décroît de <span class=\"kw-chiffre\">-10 %/min</span> sans <span class=\"kw-def\">RCP</span> (≈ nulle après <span class=\"kw-chiffre\">10 min</span>) ; <span class=\"kw-def\">no-flow</span> de très mauvais pronostic si <span class=\"kw-chiffre\">&gt; 5 min</span>, survie quasi nulle si <span class=\"kw-chiffre\">&gt; 10 min</span> ; <span class=\"kw-ttt\">CEE</span> idéalement <span class=\"kw-chiffre\">&lt; 3 min</span><br><strong>1er geste :</strong> reconnaissance en <span class=\"kw-chiffre\">&lt; 10 s</span> puis <span class=\"kw-ttt\">alerte (15 / 18 / 112)</span> + <span class=\"kw-ttt\">RCP immédiate</span> (MCE), en notant l'heure</p>","hospit":"<p><strong>Pré-hospitalier :</strong> <span class=\"kw-def\">RCP</span> de base par le témoin (3 premiers maillons) puis <span class=\"kw-ttt\">RCP spécialisée SMUR</span> (4e maillon)<br><strong>Post-RACS :</strong> <span class=\"kw-ttt\">réanimation</span> — soins spécialisés post-arrêt cardiaque (5e maillon)<br><strong><span class=\"kw-ttt\">Reperfusion</span> :</strong> <span class=\"kw-imagerie\">coronarographie</span> immédiate si <span class=\"kw-etio\">SCA</span> avec <span class=\"kw-radio\">sus-décalage ST</span> à l'<span class=\"kw-imagerie\">ECG</span> post-RACS</p>","redflags":"<ul><li>Reconnaissance de l'<span class=\"kw-alerte\">ACR</span> : <span class=\"kw-clinique\">inconscient</span> (ne bouge pas, ne répond pas), ne respire pas ou <span class=\"kw-clinique\">respiration agonique (gasps)</span> = absence de respiration → débuter la <span class=\"kw-def\">RCP</span></li><li>Absence de <span class=\"kw-clinique\">pouls carotidien/fémoral</span> (recherche <span class=\"kw-chiffre\">&lt; 10 s</span>, non systématique)</li><li>État de mort apparente : <span class=\"kw-clinique\">perte d'urines et de selles</span>, parfois <span class=\"kw-clinique\">mouvements cloniques</span> (hypoxie cérébrale)</li><li>Facteurs de mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-alerte\">asystolie</span> initiale, <span class=\"kw-def\">no-flow</span> prolongé, absence de témoin</li><li>Enfant — <span class=\"kw-alerte\">décompensation</span> annonçant l'<span class=\"kw-alerte\">ACR</span> : <span class=\"kw-alerte\">troubles de la conscience</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-alerte\">épuisement respiratoire (apnées)</span>, <span class=\"kw-alerte\">PAS effondrée</span></li></ul>","principes":"<p><span class=\"kw-def\">RCP</span> immédiate et ininterrompue ; l'analyse du rythme est le pivot décisionnel (choquable <span class=\"kw-bio\">vs</span> non choquable).</p><p><strong>Chaîne de survie (5 maillons)</strong></p><p>L'absence d'un seul maillon supprime tout espoir de succès</p><ul><li>1. <span class=\"kw-ttt\">Alerte précoce</span> : <span class=\"kw-alerte\">SAMU</span> (<span class=\"kw-chiffre\">15</span>), pompiers (<span class=\"kw-chiffre\">18</span>), secours (<span class=\"kw-chiffre\">112</span>)</li><li>2. <span class=\"kw-ttt\">RCP précoce</span> : MCE + ventilation</li><li>3. <span class=\"kw-ttt\">Défibrillation précoce</span> (DAE)</li><li>4. <span class=\"kw-ttt\">RCP spécialisée</span> (<span class=\"kw-alerte\">SMUR</span>) sur place</li><li>5. <span class=\"kw-ttt\">Soins spécialisés post-arrêt cardiaque</span></li></ul><p><strong><span class=\"kw-def\">RCP</span> de base — ABCD (30:2)</strong></p><ul><li><strong>A — Airway :</strong> bascule de la tête + subluxation mandibulaire (<span class=\"kw-ci\">sauf suspicion de traumatisme cervical</span>), retrait des corps étrangers, canule de Guedel</li><li><strong>B — Breathing :</strong> 2 insufflations (≈ <span class=\"kw-chiffre\">1 s</span>) toutes <span class=\"kw-clinique\">les</span> 30 compressions, BAVU + O2 ; <span class=\"kw-alerte\">hyperventilation néfaste</span> (diminue le retour veineux)</li><li><strong>C — Circulation :</strong> MCE prioritaire, plan dur, compressions <span class=\"kw-chiffre\">5-6 cm</span> à <span class=\"kw-chiffre\">100-120/min</span>, rythme <span class=\"kw-chiffre\">30:2</span>, relais toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 min</span></li><li><strong>D — DAE :</strong> dès disponible ; rythme choquable → <span class=\"kw-alerte\">choc</span> puis MCE <span class=\"kw-chiffre\">2 min</span> ; rythme non choquable → poursuivre la <span class=\"kw-def\">RCP</span></li></ul><p><strong><span class=\"kw-def\">RCP</span> spécialisée — rythme choquable (<span class=\"kw-alerte\">FV</span> / TV sans pouls)</strong></p><p>Exception : patient déjà monitoré devant des secours équipés → 3 <span class=\"kw-ttt\">CEE</span> en salve sans MCE intercalé</p><ul><li><span class=\"kw-ttt\">CEE 150 J</span> biphasique puis MCE ≥ <span class=\"kw-chiffre\">2 min</span> avant <span class=\"kw-def\">réévaluation</span></li><li>Persistance → 2e <span class=\"kw-ttt\">CEE</span>, puis 3e CEE + <span class=\"kw-ttt\">adrénaline 1 mg</span> + <span class=\"kw-ttt\">amiodarone 300 mg</span></li><li>Persistance → 4e <span class=\"kw-ttt\">CEE</span> + <span class=\"kw-ttt\">adrénaline 1 mg</span> + <span class=\"kw-ttt\">amiodarone 150 mg</span></li><li>Rythme sinusal restauré → <span class=\"kw-ttt\">amiodarone 900 mg/24h IVSE</span></li></ul><p><strong><span class=\"kw-def\">RCP</span> spécialisée — rythme non choquable (<span class=\"kw-alerte\">asystolie</span> / dissociation électromécanique)</strong></p><ul><li>Pas de <span class=\"kw-ttt\">CEE</span></li><li><span class=\"kw-ttt\">Adrénaline 1 mg IVD toutes les 3-5 min</span> (incontournable en <span class=\"kw-alerte\">asystolie</span>)</li><li>MCE continu <span class=\"kw-chiffre\">2 min</span> puis réanalyse du rythme et du pouls</li></ul><p><strong>Mesures associées</strong></p><ul><li><strong>Oxygénation :</strong> BAVU + O2 <span class=\"kw-chiffre\">≥ 15 L/min</span> ; IOT non prioritaire (sauf cause hypoxique), <span class=\"kw-ttt\">FiO2 100 %</span>, capnographie continue, insufflations <span class=\"kw-chiffre\">10/min</span></li><li><strong>Abord vasculaire :</strong> VVP en 1re intention (ne pas perdre <span class=\"kw-chiffre\">&gt; 3 min</span>) → <span class=\"kw-ttt\">voie intra-osseuse</span> (tibia / humérus) → VVC en <span class=\"kw-chiffre\">2e intention</span></li><li><strong>Autres médicaments :</strong> <span class=\"kw-ttt\">lidocaïne</span> si pas d'<span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">sulfate de magnésium</span> si <span class=\"kw-alerte\">torsade de pointes</span> / hypomagnésémie ; <span class=\"kw-ttt\">bicarbonate 8,4 %</span> si hyperkaliémie, acidose ou intoxication aux stabilisants de membrane</li><li><strong>Remplissage :</strong> sérum salé isotonique uniquement si <span class=\"kw-etio\">ACR hypovolémique</span> (délétère sinon)</li></ul><p><strong>Causes réversibles — 4H / 4T</strong></p><p>Traitement étiologique en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ttt\">drainage</span> péricardique, exsufflation/drainage, <span class=\"kw-ttt\">thrombolyse</span> (<span class=\"kw-alerte\">IDM</span>/EP), correction K+/Mg2+, gluconate de calcium, réchauffement</p><ul><li><strong>4H :</strong> <span class=\"kw-etio\">Hypoxie</span>, <span class=\"kw-etio\">Hypo/Hyperkaliémie</span>, <span class=\"kw-etio\">Hypothermie</span>, <span class=\"kw-etio\">Hypovolémie</span></li><li><strong>4T :</strong> <span class=\"kw-etio\">Tamponnade</span>, Tension pneumothorax (<span class=\"kw-etio\">PNO compressif</span>), Thrombose (<span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">EP</span>), <span class=\"kw-etio\">Toxiques</span></li></ul><p><strong>Spécificités pédiatriques (<span class=\"kw-alerte\">ACR</span> le plus souvent secondaire, asphyxique)</strong></p><ul><li><span class=\"kw-def\">RCP</span> de base : <span class=\"kw-ttt\">5 insufflations</span> initiales puis <span class=\"kw-chiffre\">15:2</span> ; alerter le <span class=\"kw-alerte\">SAMU</span> après <span class=\"kw-chiffre\">1 min</span> de RCP</li><li>MCE : <span class=\"kw-chiffre\">2 doigts</span> si <span class=\"kw-chiffre\">&lt; 1 an</span>, talon d'1 main si <span class=\"kw-chiffre\">&gt; 1 an</span>, dépression <span class=\"kw-chiffre\">1/3</span> du thorax à <span class=\"kw-chiffre\">100-120/min</span></li><li><span class=\"kw-ttt\">DAE 4 J/kg</span> (dès <span class=\"kw-chiffre\">≥ 1 an</span>) ; <span class=\"kw-ttt\">adrénaline 10 µg/kg</span> ; <span class=\"kw-ttt\">amiodarone 5 mg/kg</span></li><li>Rythme préterminal le plus souvent <span class=\"kw-alerte\">non défibrillable (asystolie 75 %)</span> ; rythmes choquables ≈ <span class=\"kw-chiffre\">10 %</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Diagnostic étiologique</span> post-RACS</strong></p><ul><li><span class=\"kw-bio\">ECG immédiat</span> : <span class=\"kw-radio\">sus-décalage ST</span> → <span class=\"kw-imagerie\">coronarographie</span> immédiate (cause principale = <span class=\"kw-etio\">ischémie coronaire</span>)</li><li>Sans sus-ST : rechercher une cause extra-cardiaque, sinon <span class=\"kw-imagerie\">coronarographie</span> rapide</li><li><span class=\"kw-imagerie\">ETT</span> (cœur pulmonaire aigu, épanchement péricardique), <span class=\"kw-bio\">ionogramme / gazométrie</span> (dyskaliémie), auscultation pulmonaire (PNO)</li></ul><p><strong>Neuroprotection & contrôle des ACSOS</strong></p><ul><li><span class=\"kw-ttt\">Contrôle ciblé de température 32-36°C</span> ≥ <span class=\"kw-chiffre\">24h</span> ; <span class=\"kw-alerte\">prévenir l'hyperthermie</span> (laisse des séquelles)</li><li><span class=\"kw-ttt\">Sédation 24-48h</span> ; ventilation pour <span class=\"kw-bio\">SpO2</span> <span class=\"kw-chiffre\">94-98 %</span> (éviter hyperoxie, hypoxie et hypercapnie)</li><li>Lutte contre l'hyperglycémie (<span class=\"kw-alerte\">œdème cérébral</span>) ; <span class=\"kw-ci\">glucocorticoïdes inefficaces</span></li><li><span class=\"kw-def\">Pronostic</span> cérébral réévalué <span class=\"kw-chiffre\">J1-J3</span> : <span class=\"kw-def\">score de Glasgow</span>, <span class=\"kw-imagerie\">EEG</span>, potentiels évoqués sensitifs</li></ul><p><strong>Préservation cardiaque & assistance</strong></p><ul><li>Sidération / hibernation myocardique possible ; <span class=\"kw-ttt\">dobutamine</span> si troubles de la contractilité</li><li><span class=\"kw-ttt\">ECMO</span> (<span class=\"kw-def\">RCP</span> extra-corporelle) si <span class=\"kw-alerte\">ACR</span> réfractaire aux mesures de <span class=\"kw-alerte\">réanimation</span></li></ul><p><strong>Critères d'arrêt de la <span class=\"kw-def\">RCP</span></strong></p><ul><li><span class=\"kw-def\">ACR réfractaire</span> = pas de RACS après <span class=\"kw-chiffre\">30 min</span> de <span class=\"kw-def\">RCP</span> spécialisée bien conduite</li><li>Arrêt en <span class=\"kw-ci\">l'absence de facteur protecteur cérébral</span> (<span class=\"kw-clinique\">hypothermie</span>, noyade, intoxication)</li><li>Extra-hospitalier, tous présents : sans témoin, rythme initial non choquable, <span class=\"kw-alerte\">asystolie &gt; 20 min</span> sous <span class=\"kw-def\">RCP</span> continue, pas de cause réversible</li><li>Décision <span class=\"kw-ttt\">médicale et collégiale</span> ; chez l'enfant, arrêt envisagé après <span class=\"kw-chiffre\">&gt; 20 min</span> de <span class=\"kw-def\">RCP</span></li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/reconnaitre-gravite-dun-enfant-malade-arret-cardiorespiratoire","label":"Pedia-univ — Reconnaitre gravite dun enfant malade arret cardiorespiratoire"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/13.%20Arr%C3%AAt%20cardiaque.pdf","label":"CeMIR — 13. arrêt cardiaque"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"ACR confirmé — Inconscient, apnée ou gasps, pouls absent &lt; 10 s","detail":"<h4>CAT — Algorithme universel de <span class=\"kw-def\">RCP</span> de l'adulte — Après reconnaissance de l'<span class=\"kw-alerte\">ACR</span>, alerte et RCP de base débutée</h4>","branches":[{"to":"q-rythme","label":"Alerte + RCP + analyse du rythme","color":"blue"}]},{"id":"q-rythme","kind":"decision","label":"Rythme choquable (FV / TV sans pouls) sur le scope ?","branches":[{"to":"q-racs","label":"Choquable (FV / TV) → CEE 150 J + RCP 2 min","color":"red"},{"to":"q-arret","label":"Non choquable (asystolie / AESP)","color":"amber"}]},{"id":"q-racs","kind":"decision","label":"RACS obtenu (pouls + PA stable) ?","branches":[{"to":"t-postarret","label":"Oui — RACS (pouls + PA)","color":"green"},{"to":"t-fv-refrac","label":"Non — persistance après 3e choc","color":"red"}]},{"id":"t-postarret","kind":"terminal","label":"RACS — soins post-arrêt cardiaque","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">ECG immédiat</span> ; <span class=\"kw-imagerie\">coronarographie</span> immédiate si <span class=\"kw-radio\">sus-décalage ST</span></li><li><span class=\"kw-ttt\">Contrôle ciblé de température 32-36°C</span> ≥ <span class=\"kw-chiffre\">24h</span>, <span class=\"kw-ttt\">sédation 24-48h</span></li><li>Ventilation <span class=\"kw-bio\">SpO2</span> <span class=\"kw-chiffre\">94-98 %</span>, lutte contre l'hyperglycémie et l'<span class=\"kw-clinique\">hyperthermie</span> (ACSOS)</li></ul><h4>Orientation</h4><ul><li><span class=\"kw-ttt\">Réanimation</span> — soins spécialisés post-arrêt cardiaque (5e maillon)</li></ul>"},{"id":"t-fv-refrac","kind":"terminal","label":"FV / TV réfractaire (pas de RACS)","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">CEE 150 J</span> itératif toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 min</span>, MCE non interrompu</li><li><span class=\"kw-ttt\">Adrénaline 1 mg</span> + <span class=\"kw-ttt\">amiodarone 300 mg</span> au 3e <span class=\"kw-alerte\">choc</span>, <span class=\"kw-ttt\">amiodarone 150 mg</span> au 4e</li><li>Rechercher et traiter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">causes réversibles (4H / 4T)</span></li><li>Discuter <span class=\"kw-ttt\">ECMO</span> (<span class=\"kw-def\">RCP</span> extra-corporelle) si <span class=\"kw-alerte\">ACR</span> réfractaire</li></ul>"},{"id":"q-arret","kind":"decision","label":"Critères d'arrêt de la RCP réunis ? — Sans témoin, asystolie &gt; 20 min, pas de cause réversible","branches":[{"to":"t-traiter-cause","label":"Non — poursuivre la RCP","color":"red"},{"to":"t-arret","label":"Oui — critères réunis","color":"blue"}]},{"id":"t-traiter-cause","kind":"terminal","label":"Rythme non choquable — adrénaline + cause","color":"red","detail":"<h4>Conduite</h4><ul><li>Pas de <span class=\"kw-ttt\">CEE</span> (<span class=\"kw-alerte\">asystolie</span> / dissociation électromécanique)</li><li><span class=\"kw-ttt\">Adrénaline 1 mg IVD toutes les 3-5 min</span>, MCE continu</li><li><span class=\"kw-def\">Réévaluation</span> du rythme et du pouls toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 min</span></li><li>Traiter la <span class=\"kw-etio\">cause réversible (4H / 4T)</span></li></ul>"},{"id":"t-arret","kind":"terminal","label":"Arrêt de la réanimation","color":"blue","detail":"<h4>Décision</h4><ul><li><span class=\"kw-def\">ACR réfractaire</span> : pas de RACS après <span class=\"kw-chiffre\">30 min</span> de <span class=\"kw-def\">RCP</span> spécialisée</li><li>Critères (tous présents) : sans témoin, rythme initial non choquable, <span class=\"kw-alerte\">asystolie &gt; 20 min</span> sous <span class=\"kw-def\">RCP</span>, pas de cause réversible</li><li>Décision <span class=\"kw-ttt\">médicale, collégiale</span>, en <span class=\"kw-ci\">l'absence de facteur protecteur</span> (<span class=\"kw-clinique\">hypothermie</span>, intoxication)</li></ul>"}]},"cards":[]};